def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    row_groups, col_groups = [], []
    start = 0
    for r in range(h):
        if r in sep_rows:
            if start < r:
                row_groups.append(range(start, r))
            start = r + 1
    if start < h:
        row_groups.append(range(start, h))

    start = 0
    for c in range(w):
        if c in sep_cols:
            if start < c:
                col_groups.append(range(start, c))
            start = c + 1
    if start < w:
        col_groups.append(range(start, w))

    separators = {(r, c) for r in sep_rows for c in range(w)}
    separators.update((r, c) for c in sep_cols for r in range(h))
    from collections import Counter
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if (r, c) not in separators)
    background = counts.most_common(1)[0][0]

    out = []
    for rows in row_groups:
        line = []
        for cols in col_groups:
            n = sum(grid[r][c] != background for r in rows for c in cols)
            line.append(1 if n == 2 else background)
        out.append(line)
    return out
